1|/* Browser-local favorite drinks. There are deliberately no accounts or server
2|   identifiers here: a usual belongs to this browser and is scoped to a store. */
3|(function (root) {
4|  'use strict';
5|
6|  const STORAGE_KEY = 'boba-builder:favorites:v1';
7|  const MAX_PER_STORE = 8;
8|  const AXES = ['size', 'sugar', 'ice', 'milk', 'temperature'];
9|
10|  function storageOrDefault(storage) {
11|    return storage || root.localStorage;
12|  }
13|
14|  function text(value, limit) {
15|    return typeof value === 'string' ? value.trim().slice(0, limit) : '';
16|  }
17|
18|  function clean(raw) {
19|    if (!raw || typeof raw !== 'object') return null;
20|    const favorite = {
21|      id: text(raw.id, 100),
22|      name: text(raw.name, 50),
23|      restaurant_id: text(raw.restaurant_id, 100),
24|      item_id: text(raw.item_id, 160),
25|      drink: text(raw.drink, 160),
26|      size: text(raw.size, 80),
27|      sugar: text(raw.sugar, 80),
28|      ice: text(raw.ice, 80),
29|      milk: text(raw.milk, 80),
30|      temperature: text(raw.temperature, 80),
31|      toppings: Array.isArray(raw.toppings)
32|        ? raw.toppings.map((value) => text(value, 100)).filter(Boolean).slice(0, 20) : [],
33|      quantity: Math.max(1, Math.min(20, Number.parseInt(raw.quantity, 10) || 1)),
34|      notes: text(raw.notes, 500),
35|      created_at: text(raw.created_at, 40),
36|      updated_at: text(raw.updated_at, 40),
37|    };
38|    if (!favorite.id || !favorite.name || !favorite.restaurant_id || !favorite.drink) return null;
39|    return favorite;
40|  }
41|
42|  function read(storage) {
43|    try {
44|      const parsed = JSON.parse(storageOrDefault(storage).getItem(STORAGE_KEY) || '[]');
45|      return Array.isArray(parsed) ? parsed.map(clean).filter(Boolean) : [];
46|    } catch (_error) {
47|      return [];
48|    }
49|  }
50|
51|  function write(storage, favorites) {
52|    storageOrDefault(storage).setItem(STORAGE_KEY, JSON.stringify(favorites));
53|  }
54|
55|  function id() {
56|    if (root.crypto && typeof root.crypto.randomUUID === 'function') {
57|      return root.crypto.randomUUID();
58|    }
59|    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
60|  }
61|
62|  function list(storage, restaurantId) {
63|    const favorites = read(storage);
64|    if (!restaurantId) return favorites;
65|    return favorites.filter((favorite) => favorite.restaurant_id === restaurantId);
66|  }
67|
68|  function fromOrder(name, payload, restaurantId, item, existing) {
69|    const now = new Date().toISOString();
70|    return clean({
71|      id: existing ? existing.id : id(),
72|      name: name,
73|      restaurant_id: restaurantId,
74|      item_id: item && item.id,
75|      drink: payload.drink,
76|      size: payload.size,
77|      sugar: payload.sugar,
78|      ice: payload.ice,
79|      milk: payload.milk,
80|      temperature: payload.temperature,
81|      toppings: payload.toppings,
82|      quantity: payload.quantity,
83|      notes: payload.notes,
84|      created_at: (existing && existing.created_at) || now,
85|      updated_at: now,
86|    });
87|  }
88|
89|  function save(storage, favorite) {
90|    const cleaned = clean(favorite);
91|    if (!cleaned) throw new Error('Give this usual a name before saving it.');
92|    const favorites = read(storage);
93|    const existingIndex = favorites.findIndex((entry) => entry.id === cleaned.id);
94|    const countAtStore = favorites.filter(
95|      (entry) => entry.restaurant_id === cleaned.restaurant_id && entry.id !== cleaned.id
96|    ).length;
97|    if (existingIndex < 0 && countAtStore >= MAX_PER_STORE) {
98|      throw new Error(`You can keep up to ${MAX_PER_STORE} usuals for each store.`);
99|    }
100|    if (existingIndex >= 0) favorites[existingIndex] = cleaned;
101|    else favorites.unshift(cleaned);
102|    write(storage, favorites);
103|    return cleaned;
104|  }
105|
106|  function remove(storage, favoriteId) {
107|    const favorites = read(storage);
108|    const kept = favorites.filter((favorite) => favorite.id !== favoriteId);
109|    if (kept.length === favorites.length) return false;
110|    write(storage, kept);
111|    return true;
112|  }
113|
114|  function drinkKey(value) {
115|    return text(value, 160).toLocaleLowerCase().replace(/\s+/g, ' ');
116|  }
117|
118|  function findItem(favorite, menu) {
119|    const items = menu && Array.isArray(menu.items) ? menu.items : [];
120|    const byId = items.find((candidate) => favorite.item_id
121|      && String(candidate.id) === String(favorite.item_id));
122|    if (byId) return byId;
123|    const wantedName = drinkKey(favorite.drink);
124|    return items.find((candidate) => drinkKey(candidate.name) === wantedName) || null;
125|  }
126|
127|  function compatibility(favorite, menu) {
128|    if (!favorite || !menu || favorite.restaurant_id !== menu.restaurant_id) {
129|      return { ok: false, reason: 'This usual belongs to a different store.' };
130|    }
131|    const item = findItem(favorite, menu);
132|    if (!item) return { ok: false, reason: 'This drink is no longer on this store menu.' };
133|
134|    const groups = Array.isArray(item.option_groups) ? item.option_groups : [];
135|    const offeredAxes = {};
136|    for (const group of groups.filter((candidate) => candidate.axis !== 'toppings')) {
137|      offeredAxes[group.axis] = true;
138|      const offered = (group.options || []).map((option) => option.label);
139|      const value = favorite[group.axis] || '';
140|      const minimum = Math.max(Number(group.min || 0), group.required ? 1 : 0);
141|      if ((minimum && !value) || (value && !offered.includes(value))) {
142|        return { ok: false, item: item, reason: `${group.name} needs to be reviewed.` };
143|      }
144|    }
145|    for (const axis of AXES) {
146|      if (favorite[axis] && !offeredAxes[axis]) {
147|        return { ok: false, item: item, reason: 'Its available options have changed.' };
148|      }
149|    }
150|
151|    const remaining = favorite.toppings.slice();
152|    for (const group of groups.filter((candidate) => candidate.axis === 'toppings')) {
153|      const offered = (group.options || []).map((option) => option.label);
154|      let selected = [];
155|      if (group.multiselect) {
156|        selected = remaining.filter((value) => offered.includes(value));
157|        selected.forEach((value) => remaining.splice(remaining.indexOf(value), 1));
158|      } else {
159|        const index = remaining.findIndex((value) => offered.includes(value));
160|        if (index >= 0) selected = remaining.splice(index, 1);
161|      }
162|      const minimum = Math.max(Number(group.min || 0), group.required ? 1 : 0);
163|      if (selected.length < minimum || (group.max && selected.length > group.max)) {
164|        return { ok: false, item: item, reason: `${group.name} needs to be reviewed.` };
165|      }
166|    }
167|    if (remaining.length) {
168|      return { ok: false, item: item, reason: 'One or more toppings are no longer offered.' };
169|    }
170|
171|    return {
172|      ok: true,
173|      item: item,
174|      payload: {
175|        drink: item.name,
176|        size: favorite.size,
177|        sugar: favorite.sugar,
178|        ice: favorite.ice,
179|        milk: favorite.milk,
180|        temperature: favorite.temperature,
181|        toppings: favorite.toppings.slice(),
182|        quantity: favorite.quantity,
183|        notes: favorite.notes,
184|      },
185|    };
186|  }
187|
188|  root.BobaFavorites = {
189|    STORAGE_KEY: STORAGE_KEY,
190|    MAX_PER_STORE: MAX_PER_STORE,
191|    list: list,
192|    fromOrder: fromOrder,
193|    save: save,
194|    remove: remove,
195|    findItem: findItem,
196|    compatibility: compatibility,
197|  };
198|}(window));

