1|/* Solo ordering: one person ordering just for themselves.
2|
3|   The page is usuals-first on purpose — that is the advantage over the Kung Fu
4|   Tea app (see docs/task27-solo-order.md). My Usuals (browser-local favorites
5|   with complete modifier sets) and recent saved orders sit above the menu, and
6|   each usual has a one-tap Reorder that skips the editor and goes straight to
7|   the shared preview → cart handoff. Everything else (menu, modifiers,
8|   estimates) is the same captured-menu pipeline as the group flow. */
9|
10|(function () {
11|  'use strict';
12|
13|  const MAX_VISIBLE_DRINKS = 40;
14|  const STORE_KEY = 'boba-builder:solo-store';
15|  const NAME_KEY = 'boba-builder:solo-name';
16|  const SAVED_TOKEN_KEY = 'boba-builder:saved-orders-token';
