18|  /* --- pure helpers (also the tested surface) --------------------------- */
19|
20|  // A favorite record -> the POST body for /api/solo-orders. The full modifier
21|  // set travels with it, which is exactly what the official app cannot do
22|  // without an account: one tap rebuilds the whole drink.
23|  function quickPayload(favorite) {
24|    const source = favorite || {};
25|    return {
26|      drink: source.drink,
27|      size: source.size || '',
28|      sugar: source.sugar || '',
29|      ice: source.ice || '',
30|      milk: source.milk || '',
31|      temperature: source.temperature || '',
32|      toppings: (source.toppings || []).slice(),
33|      quantity: source.quantity || 1,
34|      notes: source.notes || '',
35|    };
36|  }
37|
38|  function validatePayload(payload) {
39|    if (!payload || !String(payload.drink || '').trim()) return 'pick a drink first';
40|    const quantity = Number(payload.quantity);
41|    if (!Number.isFinite(quantity) || Math.floor(quantity) !== quantity) {
42|      return "that quantity isn't a number";
43|    }
44|    if (quantity < 1) return "a quantity of nothing isn't an order";
45|    if (quantity > 20) return 'at most 20 of one drink per solo order';
46|    return '';
47|  }
48|
49|  // The order-level body for POST /api/solo-orders: one person's drinks.
50|  function buildOrderPayload(restaurantId, person, drinks) {
51|    return {
52|      restaurant_id: restaurantId,
53|      person: person,
54|      drinks: drinks,
55|    };
56|  }
57|
58|  if (typeof window !== 'undefined') {
59|    window.BobaSolo = {
60|      quickPayload: quickPayload,
61|      validatePayload: validatePayload,
62|      buildOrderPayload: buildOrderPayload,
63|    };
64|  }
65|
