  // are skipped with their reason — the draft has no edit flow, so a stale
  // entry cannot be fixed there.
  function loadTemplate(template) {
    if (!window.BobaOrderTemplates) return;
    const payloads = window.BobaOrderTemplates.toSoloDrinks(template);
    const multi = window.BobaOrderTemplates.peopleCount(template) > 1;
    let added = 0;
    const skipped = [];
    (template.entries || []).forEach((entry, index) => {
      const check = menu
        ? window.BobaOrderTemplates.entryCompatibility(entry, menu)
        : { ok: true, payload: payloads[index] };
      if (!check.ok) {
        skipped.push(entry.drink);
        return;
      }
      const detail = (multi ? `${entry.person} · ` : '') + favoriteOptionsText(check.payload);
      if (addToDraft(check.payload, check.payload.drink, detail)) added += 1;
