  if (!elements.form.reportValidity() || !validateSelections()) return;
  ... budgetBlocked check ...
  elements.submit.disabled = true;
  setFormStatus('Confirming your drink…', 'busy');
  const payload = buildPayload();
  const id = confirmingSuggestionId;
  try {
    ... same as confirm but then favorite-save handling? Keep it simple: reuse confirmSuggestion but it calls resetEditor which clears state... confirmSuggestion(suggestion...) needs the suggestion object — find by id in session.suggestions.
  }
}
```
